_current = "en"


def set_language(code: str) -> None:
    global _current
    _current = code if code in LANGUAGES else "en"


def current() -> str:
    return _current


def is_rtl() -> bool:
    return _current in RTL


def tr(text: str) -> str:
    """Translate an English UI string; unknown strings fall back to English."""
    return _T.get(_current, {}).get(text, text)
